import{_ as t}from"./chunks/image27.BxJp-sZ3.js";import{_ as a}from"./chunks/image10.CXG-iZ2X.js";import{_ as o}from"./chunks/image18.CewVGPWQ.js";import{_ as n}from"./chunks/2.BRgDBKom.js";import{_ as i,o as r,c as s,am as l}from"./chunks/framework.CenUaW7a.js";const d="/projects/AiMechaM1/en/advanced-kit/assets/3.Vo3o4iHf.webp",c="/projects/AiMechaM1/en/advanced-kit/assets/image22.D3kXXqT2.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image23.0oSMPI-6.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image24.DL4TRaSB.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image25.BG8FKg6i.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image26.gY01D3YU.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image28.B4FL996V.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image29.CevtEQYv.png",w="/projects/AiMechaM1/en/advanced-kit/assets/image30.D8eO-Hm9.png",y="/projects/AiMechaM1/en/advanced-kit/assets/image31.BTX-lPve.png",_="/projects/AiMechaM1/en/advanced-kit/assets/image32.DD1DL47n.png",z=JSON.parse('{"title":"3.3 Lesson 3: Steering and Fixed-Point Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.3 Lesson 3 Steering and Point-to-Point Control.md","filePath":"docs/3. Course materials/3.3 Lesson 3 Steering and Point-to-Point Control.md"}'),v={name:"docs/3. Course materials/3.3 Lesson 3 Steering and Point-to-Point Control.md"};function b(x,e,k,M,P,S){return r(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-3-lesson-3-steering-and-fixed-point-control" tabindex="-1">3.3 Lesson 3: Steering and Fixed-Point Control <a class="header-anchor" href="#_3-3-lesson-3-steering-and-fixed-point-control" aria-label="Permalink to &quot;3.3 Lesson 3: Steering and Fixed-Point Control&quot;">​</a></h1><h2 id="_3-3-1-lesson-introduction" tabindex="-1">3.3.1 Lesson Introduction <a class="header-anchor" href="#_3-3-1-lesson-introduction" aria-label="Permalink to &quot;3.3.1 Lesson Introduction&quot;">​</a></h2><p>As the third introductory lesson for the AiMecha M1, this module serves as the core of the hardware overview and motion fundamentals unit. Building on the previous two lessons, it looks into the principles of Mecanum wheel turning and its programming implementation. Starting with force analysis, the lesson systematically covers three motion modes: forward/backward movement, differential turning, and in-place rotation. Through three progressive tasks advancing from single-wheel control to encapsulated command invocation, this lesson completes a practical example of &quot;moving forward for 0.5 meters followed by rotating 90 degrees in place and stopping&quot;, helping establish a speed-differential control mindset and hierarchical encapsulated programming concepts.</p><h2 id="_3-3-2-learning-objectives" tabindex="-1">3.3.2 Learning Objectives <a class="header-anchor" href="#_3-3-2-learning-objectives" aria-label="Permalink to &quot;3.3.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the principles of differential speed control and the mechanics behind how a Mecanum-wheel robot executes left/right turns and in-place rotations. Identify the wheel speed ratios for the three basic motion modes, as well as the inverse relationship between turning radius and speed differential.</p><p><strong>2.</strong> Control the rotation direction and speed of all four wheels independently using single-wheel commands, and apply wheel-group controls and encapsulated motion commands to achieve various turning modes.</p><p><strong>3.</strong> Develop a layered programming mindset, &quot;low-level control, mid-level encapsulation, and high-level invocation&quot;, while cultivating an engineering approach to parameter tuning and iterative optimization.</p><p><strong>4.</strong> Connect omnidirectional mobility to real-world industrial applications such as warehouse logistics and pipeline inspection, and recognize the technical advantages of zero-radius turning in confined spaces.</p><h2 id="_3-3-3-preparation" tabindex="-1">3.3.3 Preparation <a class="header-anchor" href="#_3-3-3-preparation" aria-label="Permalink to &quot;3.3.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-wheel robot base × 1</li></ul><ul><li>Type-C USB data cable × 1</li><li>Computer running Windows or macOS × 1</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><h2 id="_3-3-4-hands-on-project" tabindex="-1">3.3.4 Hands-On Project <a class="header-anchor" href="#_3-3-4-hands-on-project" aria-label="Permalink to &quot;3.3.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This lesson program adopts a sequential execution structure, achieving various steering maneuvers by regulating the chassis power output and wheel speed ratios of the Mecanum wheel car. The system is divided into a decision-making layer and an execution layer: the decision-making layer plans motion sequences and sets parameters, controlling action durations using &quot;motion settings + delay waits&quot;. The execution layer issues speed commands to the chassis controller, driving the four Mecanum wheels according to different direction and speed combinations to synthesize the corresponding resultant motion forces. Starting from underlying single-wheel control and advancing to wheel group control and encapsulated command invocation, this process demonstrates the programming efficiency improvements brought by program abstraction and encapsulation.</p><img loading="lazy" height="540" width="960" src="'+d+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="290" width="552" src="'+c+'" class="common_img" style="width:460px;aspect-ratio:552 / 290;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Single-wheel control</td><td style="text-align:center;"><img loading="lazy" height="199" width="505" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:505 / 199;"></td><td style="text-align:left;">Independently controls the rotation speed of each wheel, with positive values for forward rotation and negative values for reverse rotation.</td></tr><tr><td style="text-align:center;">Wheel group control</td><td style="text-align:center;"><img loading="lazy" height="151" width="479" src="'+h+'" class="common_img" style="width:300px;aspect-ratio:479 / 151;"></td><td style="text-align:left;">Simultaneously controls two wheels on the same side, suitable for differential steering scenarios.</td></tr><tr><td style="text-align:center;">Fixed-distance movement</td><td style="text-align:center;"><img loading="lazy" height="62" width="547" src="'+g+'" class="common_img" style="width:400px;aspect-ratio:547 / 62;"></td><td style="text-align:left;">Sets movement distance while configuring forward or backward movement, automatically stopping upon arrival.</td></tr><tr><td style="text-align:center;">In-place steering</td><td style="text-align:center;"><img loading="lazy" height="64" width="489" src="'+m+'" class="common_img" style="width:300px;aspect-ratio:489 / 64;"></td><td style="text-align:left;">Drives two motors with speed differentials to achieve in-place rotation.</td></tr><tr><td style="text-align:center;">Motion stop</td><td style="text-align:center;"><img loading="lazy" height="90" width="342" src="'+t+'" class="common_img" style="width:160px;aspect-ratio:342 / 90;"></td><td style="text-align:left;">Sets the car to stop moving and applies an immediate brake.</td></tr><tr><td style="text-align:center;">Timing control</td><td style="text-align:center;"><img loading="lazy" height="100" width="326" src="'+a+'" class="common_img" style="width:160px;aspect-ratio:326 / 100;"></td><td style="text-align:left;">Regulates motion switching intervals to prevent actions from transitioning too quickly.</td></tr><tr><td style="text-align:center;">Event trigger</td><td style="text-align:center;"><img loading="lazy" height="72" width="397" src="'+o+'" class="common_img" style="width:200px;aspect-ratio:397 / 72;"></td><td style="text-align:left;">Program startup trigger condition.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Independently Control the Rotation Speed of Each Wheel to Implement Simple Forward and Backward Movements of the Mecanum-Wheel Car.</strong></p><ul><li><p>Trigger condition: Start the program when the A key is pressed briefly.</p></li><li><p>Forward phase: Set the speeds of all four wheels, front-left, front-right, rear-left, and rear-right, to 60 rpm.</p></li><li><p>Wait 1 s to maintain the forward state.</p></li><li><p>Backward phase: Set the speeds of all four wheels to -60 rpm.</p></li><li><p>Wait 1 s to maintain the backward state.</p></li><li><p>Set the Mecanum-wheel car to stop.</p></li></ul><img loading="lazy" height="534" width="575" src="'+u+'" class="common_img" style="width:400px;aspect-ratio:575 / 534;"><p><strong>Task 2: Configure Forward and Backward Distances to Move the Mecanum-Wheel Car Forward by 1 Meter Followed by Backward by 1 Meter.</strong></p><ul><li><p>Set the Mecanum-wheel car to move forward by 100 cm at a speed of 60 rpm.</p></li><li><p>Wait 10 s.</p></li><li><p>Set the Mecanum-wheel car to move backward by 100 cm at a speed of 60 rpm.</p></li></ul><img loading="lazy" height="213" width="573" src="'+f+'" class="common_img" style="width:400px;aspect-ratio:573 / 213;"><p><strong>Task 3: Independently Control the Rotation Speed of Each Wheel to Implement Left Turns, Right Turns, In-Place Left Turns, and In-Place Right Turns.</strong></p><ul><li><p>Left and right turns are achieved via wheel speed differentials between the left and right Mecanum wheels, where a smaller differential results in a smaller turning angle.</p></li><li><p>Left turn: Set the two wheels on the left side to 10 rpm and the two wheels on the right side to 60 rpm, and wait 1 s.</p></li><li><p>Right turn: Set the two wheels on the left side to 60 rpm and the two wheels on the right side to 10 rpm, and wait 1 s.</p></li><li><p>In-place left turn: Set the two wheels on the left side to -60 rpm and the two wheels on the right side to 60 rpm, and wait 1 s.</p></li><li><p>In-place right turn: Set the two wheels on the left side to 60 rpm and the two wheels on the right side to -60 rpm, and wait 1 s.</p></li><li><p>Finally, set the Mecanum-wheel car to stop.</p></li></ul><img loading="lazy" height="873" width="570" src="'+w+'" class="common_img" style="width:400px;aspect-ratio:570 / 873;"><p><strong>Task 4: Simplify Code Blocks and Optimize the Above Program Using Encapsulated Blocks.</strong></p><ul><li><p>Use wheel group commands to replace single-wheel settings: set left wheel group speed and set right wheel group speed.</p></li><li><p>Use in-place steering encapsulated commands: in-place left turn and in-place right turn.</p></li><li><p>Pair each action with corresponding wait seconds, and finally set the car to stop.</p></li></ul><img loading="lazy" height="532" width="582" src="'+y+'" class="common_img" style="width:400px;aspect-ratio:582 / 532;"><p><strong>Comprehensive Case: Fully Implementing Path Combination Functions</strong></p><ul><li>Objective: Move forward 0.5 m → rotate 90° clockwise in place → stop.</li><li>Set the Mecanum-wheel car to move forward by 50 cm at a rotational speed of 50 rpm.</li><li>Wait 1 s.</li><li>Set the Mecanum-wheel car to turn left in place at a rotational speed of 35 rpm.</li><li>Wait 2 s, and adjust the wheel speed and wait time to optimal parameters to achieve a 90° clockwise rotation in place.</li><li>Set the Mecanum-wheel car to stop.</li><li>Upload the program to the mecha controller to run and verify.</li></ul><img loading="lazy" height="293" width="549" src="'+_+'" class="common_img" style="width:400px;aspect-ratio:549 / 293;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Fixed-Point Steering Control</a>.</strong></p></div><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to the computer&#39;s USB port.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-3-5-expansion-and-advancement" tabindex="-1">3.3.5 Expansion and Advancement <a class="header-anchor" href="#_3-3-5-expansion-and-advancement" aria-label="Permalink to &quot;3.3.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Square Closed-Loop Path Planning</strong></p><p>Write a program to make the car autonomously trace a square trajectory with a side length of 80 cm, eventually returning to the starting position and stopping.</p><p><strong>Project 2: Custom Complex Path Driving</strong></p><p>Write a program to implement a custom path: move forward 2 m → turn left for 1 m → rotate 180° counterclockwise in place → stop.</p><h2 id="_3-3-6-q-a" tabindex="-1">3.3.6 Q&amp;A <a class="header-anchor" href="#_3-3-6-q-a" aria-label="Permalink to &quot;3.3.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the principle behind left and right turns on the Mecanum-wheel car?</strong></p><p><strong>Answer</strong>: Differential steering is utilized to generate a speed differential between the left and right wheels: the right side is faster, and the left side is slower during left turns, while the left side is faster and the right side is slower during right turns. A larger speed differential yields a smaller turning radius, whereas equal speeds result in straight driving.</p><p><strong>Q2: What is the fundamental difference between in-place rotation and standard differential turns?</strong></p><p><strong>Answer</strong>: Rotating the left and right wheels in opposite directions forms a rotational torque to achieve in-place rotation: the left wheels rotate forward, and the right wheels rotate in reverse for clockwise rotation, while the opposite applies for counterclockwise rotation. Unlike differential turns, in-place rotation sets the left and right wheels to rotate at equal speeds in opposite directions, resulting in a turning radius of zero.</p><h2 id="_3-3-7-technical-support-and-discussion" tabindex="-1">3.3.7 Technical Support and Discussion <a class="header-anchor" href="#_3-3-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.3.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a>.</p>',54)])])}const L=i(v,[["render",b]]);export{z as __pageData,L as default};
